const raw = String($json.content[0].text);
const titulo_do_dia = ((raw.match(/<titulo_do_dia>([\s\S]*?)</titulo_do_dia>/i) || [])[1] || '').trim();
const brief_whatsapp = ((raw.match(/<brief_whatsapp>([\s\S]*?)</brief_whatsapp>/i) || [])[1] || '').trim();
const fontesRaw = (raw.match(/<fontes>([\s\S]*?)</fontes>/i) || [])[1] || '';
const fontes = fontesRaw.split('
').map((l) => l.replace(/^\s*[-•*]\s*/, '').trim()).filter((l) => /^https?:///i.test(l));
if (!brief_whatsapp) throw new Error('tag <brief_whatsapp> não encontrada ou vazia no output do redator');
const userMessage = 'BRIEF DO DIA (saída do redator):
<<<
' + brief_whatsapp + '
>>>';
const system = "Você é o revisor de formato do canal de WhatsApp do IA Traduzida. Você recebe o Brief do Dia já escrito e faz APENAS ajustes de forma para o WhatsApp. Você não reescreve conteúdo, não adiciona informação, não muda o sentido de nenhuma frase.

## O que você verifica e corrige

1. Negrito no padrão WhatsApp: *asteriscos simples*. Converta qualquer **markdown duplo** ou ### cabeçalho que tenha escapado.
2. Blocos: linha em branco entre notícias; nenhum parágrafo com mais de 4 linhas no celular (~240 caracteres).
3. Links: nenhum link no meio do texto — todos numerados no bloco "Fontes:" ao final.
4. Emojis: só 🌡️ (selo) e 💬 (E eu com isso?) como fixos; remova excedentes que não agregam.
5. Comprimento: se passar de 1.900 caracteres (sem links), corte adjetivos e redundâncias — nunca corte o selo nem o "E eu com isso?" de nenhuma notícia.
6. Primeira linha: precisa funcionar como notificação push (o leitor vê só ela na tela bloqueada). Se a abertura não disser a notícia principal, reordene as palavras da própria frase para que diga.

## O que você NUNCA faz

- Adicionar ou remover notícias, fatos, números ou fontes.
- Mudar as notas do selo.
- Introduzir palavras novas de conteúdo (sinônimos para encurtar são permitidos, mantendo o registro leigo).

## Formato de saída

Responda SOMENTE com as duas tags abaixo, sem nada fora delas. O conteúdo dentro das tags é texto literal — pode conter aspas duplas, acentos, asteriscos do WhatsApp e quebras de linha sem nenhum tipo de escape. Não use blocos markdown ` ``` ` em volta.

<texto_whatsapp>
o brief final, pronto para colar no canal
</texto_whatsapp>

<ajustes_feitos>
- ajuste 1
- ajuste 2
</ajustes_feitos>";
return [{ json: { system, userMessage, titulo_do_dia, fontes, brief_original: brief_whatsapp } }];

const SITE = "https://SEU-SITE.vercel.app";

const raw = String($json.content[0].text);
const score = parseInt((raw.match(/<score>\s*(\d+)\s*<\/score>/i) || [])[1] || '0', 10);
const veredito = ((raw.match(/<veredito>\s*(\w+)\s*<\/veredito>/i) || [])[1] || 'reescreve').toLowerCase();
const probsRaw = (raw.match(/<problemas>([\s\S]*?)<\/problemas>/i) || [])[1] || '';
const problemas = probsRaw.split('\n').map((l) => l.replace(/^\s*[-•*]\s*/, '').trim()).filter((l) => l && l.toLowerCase() !== 'nenhum');
const ed = { score, veredito, problemas };
const prev = $('Parse dialeto + input editor').first().json;
const hoje = new Date().toISOString().slice(0, 10);
const slug = String(prev.titulo_do_dia).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 50) + '-' + hoje;
const flag = ed.veredito === 'libera' ? '✅ liberado' : '⚠️ revisar';
const problemasTxt = (ed.problemas || []).map((p) => '• ' + p).join('\n');
const telegramText = flag + ' — Editor-Cético: ' + ed.score + '/100\n\n' + prev.texto_final +
  '\n\n— — —\n' + (problemasTxt ? 'Apontamentos:\n' + problemasTxt : 'Sem apontamentos.') +
  '\n\nAprovar = publica no site. Recusar = descarta.';
// Telegram limita mensagens a 4096 chars; trunca a prévia (o texto completo vai pro site).
const TG_MAX = 3900;
const telegramTextSafe = telegramText.length > TG_MAX ? (telegramText.slice(0, TG_MAX) + '\n\n[...] texto completo será publicado no site') : telegramText;
const post = {
  slug, title: prev.titulo_do_dia, excerpt: String(prev.texto_final).replace(/[*_]/g, '').slice(0, 160),
  date: hoje, readTime: '3 min', category: 'Brief', content: prev.texto_final,
};
return [{ json: { telegramText: telegramTextSafe, post, apiUrl: SITE + '/api/admin/posts', score: ed.score, veredito: ed.veredito } }];

const pkg = $('Montar pacote').first().json;
const noticias = $('Montar input · redator').first().json.noticias || [];
const hoje = new Date().toISOString().slice(0, 10);
return noticias.map((n, i) => ({ json: { ...n, apiUrl: pkg.apiUrl, hoje, ordem: i } }));

const inputs = $('Montar input · post').all();
const responses = $input.all();
const posts = [];
let apiUrl = '';
for (let i = 0; i < responses.length; i++) {
  const meta = (inputs[i] && inputs[i].json && inputs[i].json._n) || {};
  if (meta.apiUrl) apiUrl = meta.apiUrl;
  const r = responses[i] && responses[i].json;
  if (!r || !r.content || !r.content[0] || !r.content[0].text) continue;
  let raw = String(r.content[0].text).trim();
  raw = raw.replace(/^```(?:markdown)?\s*/i, '').replace(/```\s*$/i, '').trim();
  const lines = raw.split('\n');
  let title = '';
  let startIdx = 0;
  for (let k = 0; k < lines.length; k++) {
    if (lines[k].trim() === '') continue;
    const mh = lines[k].match(/^#\s+(.+)/);
    if (mh) { title = mh[1].trim(); startIdx = k + 1; }
    break;
  }
  if (!title) title = meta.title || 'Sem título';
  let content = lines.slice(startIdx).join('\n');
  content = content.replace(/^\s*#{0,3}\s*excerpt\b.*(?:\n|$)/i, '').trim();
  if (!content) continue;
  const firstPara = (content.split('\n').find((l) => { const t = l.trim(); return t && !t.startsWith('#') && !t.startsWith('>'); }) || '').replace(/[*_#>\[\]]/g, '').trim();
  let excerpt = firstPara;
  if (excerpt.length > 155) {
    const cut = excerpt.slice(0, 155);
    const sp = cut.lastIndexOf(' ');
    excerpt = (sp > 60 ? cut.slice(0, sp) : cut).replace(/[\s,;:.\-]+$/, '') + '…';
  }
  const hoje = meta.hoje;
  const base = String(title).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 50);
  const slug = base + '-' + hoje + '-' + ((meta.ordem || 0) + 1);
  const category = meta.tipo === 'utilidade' ? 'Utilidade' : 'Brief';
  posts.push({ slug, title, excerpt, date: hoje, readTime: '3 min', category, content });
}
if (!posts.length) throw new Error('nenhum post individual gerado pelo LLM');
// UM item com os N posts — publicação em lote (1 escrita no Blob, sem corrida)
return [{ json: { posts, apiUrl } }];
